const [catalog,glossary]=await Promise.all(['/morphiq/catalog.json','/morphiq/glossary.json'].map(url=>fetch(url).then(r=>{if(!r.ok)throw Error('Library unavailable');return r.json();})));
const app=document.getElementById('app');
const categories=['Backgrounds','Text Animations','Micro-interactions','Power-User Systems','Hero Templates'];
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',star:'<path d="m12 3 2.8 5.7 6.3.9-4.5 4.4 1 6.2L12 17.3l-5.6 2.9 1.1-6.2L3 9.6l6.2-.9z"/>',book:'<path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1zm0 0v15"/>',layers:'<path d="m12 3 10 6-10 6L2 9zm-9 11 9 5 9-5M3 18l9 5 9-5"/>',search:'<circle cx="10.5" cy="10.5" r="7"/><path d="m16 16 5 5"/>',chevron:'<path d="m9 5 7 7-7 7"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',expand:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>',copy:'<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V4a1 1 0 0 0-1-1H4a1 1 0 0 0-1 1v11a1 1 0 0 0 1 1h4"/>',check:'<path d="m5 12 4 4 10-10"/>',play:'<path d="m8 4 13 8-13 8z"/>',pause:'<path d="M8 4v16M16 4v16"/>',reset:'<path d="M3 10a9 9 0 1 1 2 9M3 4v6h6"/>',close:'<path d="m5 5 14 14M19 5 5 19"/>',arrow:'<path d="M18 12H4m7-7-7 7 7 7"/>'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.layers}</svg>`;
const esc=value=>String(value??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const featured=['waves','grainient','submerge','morphing-text','magnetic-button','tilt','light-rays','dot-field','border-glow'];
const defaults=entry=>Object.fromEntries(entry.props.map(p=>[p.name,p.default]));
let saved=new Set();try{saved=new Set(JSON.parse(localStorage.getItem('morphiq-favorites')||'[]'));}catch{}
let category='All',query='',sort='featured',limit=24,frameObserver,activeFrames=new Map(),previewValues={},currentEntry,paused=false,currentTab='preview',reloadTimer;
const counts=cat=>catalog.filter(e=>e.category===cat).length;
const collections=[['react-background-components','Backgrounds','Atmosphere & texture','Backgrounds'],['react-text-animations','Text animations','Typography in motion','Text Animations'],['react-micro-interactions','Micro-interactions','Small details, real feedback','Micro-interactions'],['react-power-user-components','Power-user systems','Interfaces with state','Power-User Systems'],['react-hover-effects','Hover effects','Respond to a little curiosity','Hover effect'],['react-stagger-animation','Staggered motion','One thing, then the next','Stagger'],['react-drag-animations','Drag interactions','A little weight beneath the pointer','Drag'],['react-reveal-animations','Reveals','Give an entrance some intention','Reveal'],['react-spring-animation','Springs','Motion with a little personality','Spring'],['react-blur-effects','Blur effects','From soft focus to clarity','Blur'],['react-scroll-animations','Scroll animations','Move at the reader’s pace','Scroll'],['react-clip-path-mask-effects','Masks & clipping','Shape what comes into view','Clip-path'],['react-layout-animation','Layout transitions','Keep a sense of place','Layout animation'],['react-3d-tilt-effects','3D & tilt','Add another dimension','Tilt'],['framer-motion-components','Motion components','A toolkit for interactive interfaces',''],['react-webgl-backgrounds','WebGL backgrounds','Fields, light, and atmosphere','Hardware acceleration']];
const route=()=>location.pathname.replace(/\/$/,'')||'/';
function navigate(url){history.pushState({},'',url);category='All';query='';limit=24;currentTab='preview';paused=false;clearTimeout(reloadTimer);render();window.scrollTo({top:0,behavior:'instant'});}
function shell(content,section){
 return `<aside class="sidebar" id="sidebar"><a class="wordmark" href="/" aria-label="Morphiq home"><img src="/morphiq/favicon.svg" alt="" width="36" height="36">Morphiq<span class="wordmark-dot">.</span></a><div class="sidebar-caption">THE MOTION LIBRARY</div><nav aria-label="Main navigation"><a href="/components" class="nav-item ${section==='components'?'active':''}">${icon('grid')}<span>All components</span><span class="nav-count">137</span></a><a href="/favorites" class="nav-item ${section==='favorites'?'active':''}">${icon('star')}<span>Favorites</span><span class="nav-count" id="saved-count">${saved.size}</span></a><a href="/collections" class="nav-item ${section==='collections'?'active':''}">${icon('layers')}<span>Collections</span></a><a href="/cookbook" class="nav-item ${section==='cookbook'?'active':''}">${icon('book')}<span>Motion Cook Book</span></a></nav><div class="sidebar-label">EXPLORE BY CATEGORY</div><nav class="category-navigation" aria-label="Component categories">${categories.map((cat,i)=>`<a href="/components?category=${encodeURIComponent(cat)}" class="category-link ${category===cat?'selected':''}"><span class="category-symbol">${['◌','Aa','⌁','⌘','▱'][i]}</span><span>${cat==='Power-User Systems'?'Power-user systems':cat}</span><span>${counts(cat)}</span></a>`).join('')}</nav><div class="sidebar-bottom"><div class="free-note"><span class="free-mark">${icon('check')}</span><div><strong>Every preview. For everyone.</strong><p>137 components. No subscription.</p></div></div><div class="sidebar-footer"><span>MORPHIQ / 2026</span><span>v1.0</span></div></div></aside><div class="page"><header class="topbar"><button class="mobile-menu icon-button" aria-label="Open menu">${icon('menu')}</button><div class="topbar-label">${section==='components'?'COMPONENT LIBRARY':section.toUpperCase()}</div><div class="topbar-right"><a class="topbar-book" href="/cookbook">${icon('book')} The Cook Book</a></div></header><main id="main">${content}</main><footer class="site-footer"><span>Morphiq. A little motion goes a long way.</span><a href="https://motion-garden.vercel.app/" target="_blank" rel="noopener">Original animation previews: Motion Garden</a></footer></div><div class="toast" role="status" aria-live="polite"></div>`;
}
function save(slug){if(saved.has(slug))saved.delete(slug);else saved.add(slug);try{localStorage.setItem('morphiq-favorites',JSON.stringify([...saved]));}catch{}for(const button of document.querySelectorAll(`[data-save="${slug}"]`)){button.classList.toggle('is-saved',saved.has(slug));button.setAttribute('aria-pressed',String(saved.has(slug)));button.setAttribute('aria-label',(saved.has(slug)?'Remove from':'Add to')+' favorites');}document.getElementById('saved-count').textContent=saved.size;if(route()==='/favorites')renderGallery();}
function saveButton(entry,cls=''){return `<button class="save-button ${cls} ${saved.has(entry.slug)?'is-saved':''}" data-save="${entry.slug}" aria-pressed="${saved.has(entry.slug)}" aria-label="${saved.has(entry.slug)?'Remove from':'Add to'} favorites">${icon('star')}</button>`;}
function card(entry,index){return `<article class="component-card"><div class="card-preview" data-preview="${entry.slug}"><span class="preview-loader">${entry.displayName}</span><span class="component-index">${String(index+1).padStart(3,'0')}</span><a href="/components/${entry.slug}" class="preview-hitarea" aria-label="Explore ${esc(entry.displayName)}"></a>${saveButton(entry)}</div><div class="card-info"><a href="/components/${entry.slug}"><h2>${esc(entry.displayName)}</h2><p>${esc(entry.category==='Power-User Systems'?'Power-user systems':entry.category)}</p></a><span class="card-open">${icon('chevron')}</span></div></article>`;}
function galleryPage(isFavorites=false){
 const paramCategory=new URLSearchParams(location.search).get('category');if(categories.includes(paramCategory))category=paramCategory;
 return `<section class="library-heading"><div><div class="eyebrow">${isFavorites?'YOUR COLLECTION':'A PLAYGROUND FOR YOUR NEXT INTERFACE'}</div><h1>${isFavorites?'Keep the good ones.':'Make your interface <em>move.</em>'}</h1><p>${isFavorites?'Your favorite components, all in one place.':'137 interactive components. Explore the motion, turn a dial, make it yours.'}</p></div><div class="library-counter"><strong>${isFavorites?saved.size:'137'}</strong><span>${isFavorites?'SAVED COMPONENTS':'COMPONENTS / ALL FREE'}</span></div></section><div class="library-toolbar"><label class="search-box">${icon('search')}<input id="search" type="search" placeholder="Find a component…" aria-label="Search components" value="${esc(query)}"><kbd>/</kbd></label><label class="sort-label">Sort by <select id="sort" aria-label="Sort components"><option value="featured">Featured</option><option value="name" ${sort==='name'?'selected':''}>Name A–Z</option><option value="newest" ${sort==='newest'?'selected':''}>Newest</option></select></label></div><nav class="filter-tabs" aria-label="Filter components"><button data-category="All" class="${category==='All'?'selected':''}">All <span>137</span></button>${categories.map(cat=>`<button data-category="${cat}" class="${category===cat?'selected':''}">${cat==='Power-User Systems'?'Systems':cat==='Hero Templates'?'Heroes':cat==='Text Animations'?'Text':cat==='Micro-interactions'?'Interactions':cat} <span>${counts(cat)}</span></button>`).join('')}</nav><div class="gallery-heading"><h2>${isFavorites?'Your favorites':category==='All'?'The collection':category}</h2><span id="result-count"></span></div><div class="component-grid" id="component-grid"></div><div class="gallery-bottom" id="gallery-bottom"></div>`;
}
function filteredEntries(){let items=catalog.filter(e=>(route()!=='/favorites'||saved.has(e.slug))&&(category==='All'||e.category===category)&&(!query||`${e.name} ${e.description} ${e.category} ${e.cookbook.join(' ')}`.toLowerCase().includes(query.toLowerCase())));if(sort==='name')items.sort((a,b)=>a.displayName.localeCompare(b.displayName));else if(sort==='newest')items.sort((a,b)=>b.addedAt.localeCompare(a.addedAt));else items.sort((a,b)=>{const ai=featured.indexOf(a.slug),bi=featured.indexOf(b.slug);return (ai<0?999:ai)-(bi<0?999:bi)||a.displayName.localeCompare(b.displayName);});return items;}
function clearFrames(){frameObserver?.disconnect();for(const f of activeFrames.values())f.remove();activeFrames.clear();}
function renderGallery(){
 clearFrames();const entries=filteredEntries(),grid=document.getElementById('component-grid');if(!grid)return;
 document.getElementById('result-count').textContent=`${entries.length} component${entries.length===1?'':'s'}`;
 grid.innerHTML=entries.length?entries.slice(0,limit).map((e,i)=>card(e,i)).join(''):`<div class="empty-state">${icon(route()==='/favorites'?'star':'search')}<h2>${route()==='/favorites'?'Your collection starts here.':'No components found.'}</h2><p>${route()==='/favorites'?'Tap the star on any component to save it.':'Try another name, category, or motion term.'}</p><a href="/components" class="button primary">Explore components</a></div>`;
 document.getElementById('gallery-bottom').innerHTML=entries.length>limit?`<span>Showing ${Math.min(limit,entries.length)} of ${entries.length}</span><button id="load-more" class="button secondary">Show more components</button>`:`<span>${entries.length?`${entries.length} ways to bring an interface to life.`:''}</span>`;
 frameObserver=new IntersectionObserver(changes=>{for(const change of changes){const element=change.target,slug=element.dataset.preview;if(change.isIntersecting){if(!activeFrames.has(slug)){const iframe=document.createElement('iframe');iframe.src=`/previews/${slug}.html?thumbnail=1`;iframe.title=`${catalog.find(e=>e.slug===slug).displayName} preview`;iframe.tabIndex=-1;iframe.loading='lazy';iframe.setAttribute('aria-hidden','true');iframe.setAttribute('sandbox','allow-scripts allow-same-origin');element.prepend(iframe);activeFrames.set(slug,iframe);}}else{activeFrames.get(slug)?.remove();activeFrames.delete(slug);}}},{rootMargin:'80px 0px',threshold:.04});
 document.querySelectorAll('[data-preview]').forEach(element=>frameObserver.observe(element));
 document.getElementById('load-more')?.addEventListener('click',()=>{limit+=24;renderGallery();});
}
function propControl(prop,value){const name=esc(prop.name),id=`prop-${name}`,label=`<label for="${id}" title="${esc(prop.description)}">${name}</label>`;if(prop.kind==='number')return `<div class="prop-control"><div>${label}<output id="output-${name}">${esc(value)}${prop.unit?' '+esc(prop.unit):''}</output></div><input id="${id}" data-prop="${name}" type="range" min="${prop.min}" max="${prop.max}" step="${prop.step||1}" value="${esc(value)}"></div>`;if(prop.kind==='color')return `<div class="prop-control prop-inline">${label}<div class="color-control"><input type="text" data-color-text="${name}" aria-label="${name} hex value" value="${esc(value)}" pattern="#[0-9a-fA-F]{6}"><input id="${id}" data-prop="${name}" type="color" value="${esc(value)}"></div></div>`;if(prop.kind==='boolean')return `<div class="prop-control prop-inline">${label}<input id="${id}" data-prop="${name}" class="toggle" type="checkbox" ${value?'checked':''}></div>`;return `<div class="prop-control"><div>${label}</div><select id="${id}" data-prop="${name}">${prop.options.map(option=>`<option value="${esc(typeof option==='object'?option.value:option)}" ${(typeof option==='object'?option.value:option)===value?'selected':''}>${esc(typeof option==='object'?option.label:option)}</option>`).join('')}</select></div>`;}
function detailPage(entry){
 currentEntry=entry;const params=new URLSearchParams(location.search);previewValues=defaults(entry);for(const prop of entry.props){if(params.has(prop.name)){const raw=params.get(prop.name);previewValues[prop.name]=prop.kind==='number'?Math.max(prop.min,Math.min(prop.max,(raw.trim()!==''&&Number.isFinite(Number(raw))?Number(raw):prop.default))):prop.kind==='boolean'?(raw==='true'?true:raw==='false'?false:prop.default):prop.kind==='color'?(/^#[0-9a-f]{6}$/i.test(raw)?raw:prop.default):prop.options.some(option=>(typeof option==='object'?option.value:option)===raw)?raw:prop.default;}}
 const frameQuery=new URLSearchParams(Object.entries(previewValues).map(([k,v])=>[k,String(v)])).toString();
 return `<a class="back-link" href="/components">${icon('arrow')} Back to the collection</a><section class="detail-heading"><div><div class="eyebrow">${esc(entry.category)} <span class="inline-dot">·</span> FREE PREVIEW</div><h1>${esc(entry.displayName)}<span>.</span></h1><p>${esc(entry.description)}</p></div>${saveButton(entry,'detail-save')}</section><div class="detail-toolbar"><div class="view-tabs" role="tablist"><button role="tab" data-tab="preview" aria-selected="true">Preview</button><button role="tab" data-tab="source" aria-selected="false">${entry.sourceCount?'Source':'Embed'}</button></div><a id="fullscreen-link" href="/components/${entry.slug}/full?${frameQuery}" class="button small secondary">${icon('expand')} Full screen</a></div><div class="playground"><div class="demo-column"><div class="demo-surface" id="demo-surface"><iframe id="demo-frame" src="/previews/${entry.slug}.html?${frameQuery}" title="${esc(entry.displayName)} interactive preview" sandbox="allow-scripts allow-same-origin"></iframe></div><div class="demo-caption"><span>Interact with the preview</span><span>${esc(entry.category)}</span></div></div><aside class="parameter-panel"><div class="parameter-heading"><h2>Make it yours</h2><button id="reset" class="icon-button" aria-label="Reset controls" title="Reset">${icon('reset')}</button></div><div class="parameter-scroll">${entry.props.map(p=>propControl(p,previewValues[p.name])).join('')}</div>${entry.pausable?`<button id="pause" class="pause-button">${icon('pause')} <span>Pause animation</span></button>`:''}</aside></div><section id="source-panel" class="source-panel" hidden></section><section class="detail-notes"><div><span class="eyebrow">THE INGREDIENTS</span><div class="motion-tags">${entry.cookbook.map(term=>`<a href="/cookbook#${term.toLowerCase().replace(/[^a-z0-9]+/g,'-')}">${esc(term)}</a>`).join('')}</div></div><div><span class="eyebrow">DEPENDENCIES</span><p>${entry.dependencies.length?entry.dependencies.map(esc).join(' · '):'No additional packages.'}</p></div></section><div class="next-component">${neighborLink(entry,-1)}${neighborLink(entry,1)}</div>`;
}
function neighborLink(entry,offset){const index=catalog.findIndex(e=>e.slug===entry.slug),other=catalog[(index+offset+catalog.length)%catalog.length];return `<a href="/components/${other.slug}"><span>${offset<0?'PREVIOUS':'UP NEXT'}</span><strong>${esc(other.displayName)} ${icon(offset<0?'arrow':'chevron')}</strong></a>`;}
async function showSource(){const section=document.getElementById('source-panel');if(section.dataset.loaded)return;const sourceEntry=currentEntry;let files;try{files=await fetch(`/morphiq/source/${sourceEntry.slug}.json`).then(r=>{if(!r.ok)throw Error('Source unavailable');return r.json();});}catch{if(section.isConnected)section.innerHTML='<p class="source-note" role="status">Source could not be loaded. Select Preview, then Source to retry.</p>';return;}if(!section.isConnected||currentEntry!==sourceEntry)return;const embed=`<iframe\n  src="/previews/${currentEntry.slug}.html"\n  title="${currentEntry.displayName}"\n  style="width: 100%; height: 500px; border: 0;"\n></iframe>`;const display=files.length?files:[{name:'preview.html',code:embed}];section.dataset.loaded='true';section.innerHTML=`${files.length?'':'<p class="source-note">This component’s original TypeScript source was not included in the public reference files. The interactive preview is freely available to explore and embed.</p>'}<div class="source-tabs">${display.map((f,i)=>`<button data-file="${i}" class="${i===0?'active':''}">${esc(f.name)}</button>`).join('')}<button class="copy-source button small secondary">${icon('copy')} Copy</button></div><pre class="code-block" tabindex="0"><code>${esc(display[0].code)}</code></pre>`;let active=0;section.querySelectorAll('[data-file]').forEach(button=>button.onclick=()=>{active=Number(button.dataset.file);section.querySelector('code').textContent=display[active].code;section.querySelectorAll('[data-file]').forEach(b=>b.classList.toggle('active',b===button));});section.querySelector('.copy-source').onclick=()=>copy(display[active].code,'Source copied');}
function collectionMatches(entry,target){return categories.includes(target)?entry.category===target:!target||entry.cookbook.some(term=>term.toLowerCase().includes(target.toLowerCase()));}
function collectionsPage(){return `<section class="library-heading"><div><div class="eyebrow">FIND YOUR DIRECTION</div><h1>A little <em>curation.</em></h1><p>Components grouped by the motion you have in mind.</p></div></section><div class="collection-grid">${collections.map(([slug,title,description,target],i)=>`<a class="collection-card" href="/collections/${slug}"><span class="collection-number">${String(i+1).padStart(2,'0')} / COLLECTION</span><span class="collection-glyph">${['◌','Aa','⌁','⌘','↝','≈'][i%6]}</span><h2>${title}</h2><p>${description}</p><span class="collection-count">${catalog.filter(e=>collectionMatches(e,target)).length} components ${icon('chevron')}</span></a>`).join('')}</div>`;}
function collectionPage(slug){const collection=collections.find(c=>c[0]===slug)||[slug,slug.replaceAll('-',' '),'Explore these components.',''];return `<a href="/collections" class="back-link">${icon('arrow')} All collections</a><section class="library-heading"><div><div class="eyebrow">CURATED MOTION</div><h1>${esc(collection[1])}<span>.</span></h1><p>${esc(collection[2])}</p></div></section><div class="component-grid">${catalog.filter(e=>collectionMatches(e,collection[3])).map((e,i)=>card(e,i)).join('')}</div>`;}
function cookbookPage(){return `<section class="library-heading"><div><div class="eyebrow">A SHARED LANGUAGE FOR MOTION</div><h1>The Motion <em>Cook Book.</em></h1><p>A field guide to the little things that make an interface feel alive.</p></div><div class="library-counter"><strong>${glossary.length}</strong><span>MOTION INGREDIENTS</span></div></section><label class="search-box cookbook-search">${icon('search')}<input id="glossary-search" type="search" placeholder="Find a motion term…" aria-label="Search motion glossary"></label><div class="glossary-grid">${glossary.map(g=>`<article class="glossary-item" id="${g.term.toLowerCase().replace(/[^a-z0-9]+/g,'-')}" data-term="${esc(g.term.toLowerCase())}"><h2>${esc(g.term)}</h2><p>${esc(g.description)}</p><div>${catalog.filter(e=>e.cookbook.includes(g.term)).slice(0,3).map(e=>`<a href="/components/${e.slug}">${esc(e.displayName)}</a>`).join('')}</div></article>`).join('')}</div>`;}
function fullscreen(entry){currentEntry=entry;return `<div class="fullscreen-view"><iframe src="/previews/${entry.slug}.html${location.search}" title="${esc(entry.displayName)} full-screen preview" sandbox="allow-scripts allow-same-origin"></iframe><div class="fullscreen-toolbar"><a href="/components/${entry.slug}${esc(location.search)}" class="button small">${icon('close')} Exit full screen</a><span>${esc(entry.displayName)} / MORPHIQ</span></div></div>`;}
function wireFrames(){const elements=document.querySelectorAll('[data-preview]');if(!elements.length)return;frameObserver=new IntersectionObserver(changes=>{for(const change of changes){const el=change.target,slug=el.dataset.preview;if(change.isIntersecting&&!activeFrames.has(slug)){const frame=document.createElement('iframe');frame.src=`/previews/${slug}.html?thumbnail=1`;frame.title=slug+' preview';frame.tabIndex=-1;frame.loading='lazy';frame.setAttribute('sandbox','allow-scripts allow-same-origin');el.prepend(frame);activeFrames.set(slug,frame);}else if(!change.isIntersecting){activeFrames.get(slug)?.remove();activeFrames.delete(slug);}}},{rootMargin:'80px 0px'});elements.forEach(el=>frameObserver.observe(el));}
function render(){clearFrames();currentEntry=null;const pathname=route(),slug=pathname.split('/')[2],entry=/^\/components\/[^/]+(?:\/full)?$/.test(pathname)?catalog.find(e=>e.slug===slug):null;if(entry&&pathname.endsWith('/full')){app.innerHTML=fullscreen(entry);document.title=entry.displayName+' · Morphiq';return;}let section='components',content;if(entry)content=detailPage(entry);else if(pathname==='/cookbook'){section='cookbook';content=cookbookPage();}else if(pathname==='/collections'){section='collections';content=collectionsPage();}else if(pathname.startsWith('/collections/')){section='collections';content=collectionPage(slug);}else if(pathname==='/favorites'){section='favorites';content=galleryPage(true);}else if(pathname==='/'||pathname==='/components')content=galleryPage();else content='<section class="empty-state"><h1>Page not found.</h1><p>There’s plenty more to explore in the library.</p><a class="button primary" href="/components">Browse components</a></section>';app.innerHTML=shell(content,section);document.title=(entry?entry.displayName:section==='components'?'The motion library':section==='cookbook'?'Motion Cook Book':section[0].toUpperCase()+section.slice(1))+' · Morphiq';if(document.getElementById('component-grid'))renderGallery();else wireFrames();
 document.getElementById('search')?.addEventListener('input',event=>{query=event.target.value;limit=24;renderGallery();});document.getElementById('sort')?.addEventListener('change',event=>{sort=event.target.value;renderGallery();});document.getElementById('glossary-search')?.addEventListener('input',event=>{const q=event.target.value.toLowerCase();document.querySelectorAll('.glossary-item').forEach(el=>el.hidden=!el.textContent.toLowerCase().includes(q));});document.querySelector('.mobile-menu')?.addEventListener('click',()=>document.body.classList.toggle('menu-open'));
 if(entry){document.querySelectorAll('[data-prop]').forEach(input=>input.addEventListener(input.type==='range'||input.type==='color'?'input':'change',()=>updateProp(input)));document.querySelectorAll('[data-color-text]').forEach(input=>input.addEventListener('change',()=>{if(/^#[0-9a-f]{6}$/i.test(input.value)){const swatch=document.getElementById('prop-'+input.dataset.colorText);swatch.value=input.value;updateProp(swatch);}}));document.getElementById('pause')?.addEventListener('click',()=>{paused=!paused;const button=document.getElementById('pause');button.innerHTML=icon(paused?'play':'pause')+'<span>'+(paused?'Resume animation':'Pause animation')+'</span>';send({type:'morphiq:pause',paused});});document.getElementById('reset').addEventListener('click',()=>{previewValues=defaults(entry);paused=false;send({type:'morphiq:reset'});history.replaceState({},'',location.pathname);render();});}
 if(location.hash)requestAnimationFrame(()=>document.getElementById(location.hash.slice(1))?.scrollIntoView());
}
function updateProp(input){const prop=currentEntry.props.find(p=>p.name===input.dataset.prop);const value=prop.kind==='boolean'?input.checked:prop.kind==='number'?Number(input.value):input.value;previewValues[prop.name]=value;const output=document.getElementById('output-'+prop.name);if(output)output.value=value+(prop.unit?' '+prop.unit:'');const color=document.querySelector(`[data-color-text="${prop.name}"]`);if(color)color.value=value;send({type:'morphiq:values',values:{[prop.name]:value}});const params=new URLSearchParams();for(const p of currentEntry.props)if(previewValues[p.name]!==p.default)params.set(p.name,String(previewValues[p.name]));const search=params.size?'?'+params.toString():'';history.replaceState({},'',location.pathname+search);document.getElementById('fullscreen-link').href=`/components/${currentEntry.slug}/full${search}`;}
function send(data){document.getElementById('demo-frame')?.contentWindow?.postMessage(data,location.origin);}
window.addEventListener('message',event=>{const frame=document.getElementById('demo-frame');if(event.origin!==location.origin)return;if(event.data?.type==='morphiq:painted'){for(const [,iframe] of activeFrames)if(iframe.contentWindow===event.source)iframe.parentElement.classList.add('is-ready');}if(!frame||event.source!==frame.contentWindow)return;if(event.data?.type==='morphiq:ready')send({type:'morphiq:values',values:previewValues});if(event.data?.type==='morphiq:applied'&&event.data.missing?.length){clearTimeout(reloadTimer);reloadTimer=setTimeout(()=>{const url=new URL(frame.src);let changed=false;for(const key of event.data.missing){const value=String(previewValues[key]);if(url.searchParams.get(key)!==value){url.searchParams.set(key,value);changed=true;}}if(changed)frame.src=url.href;},220);}});
app.addEventListener('click',async event=>{const saveTarget=event.target.closest('[data-save]');if(saveTarget){event.preventDefault();save(saveTarget.dataset.save);return;}const cat=event.target.closest('[data-category]');if(cat){category=cat.dataset.category;limit=24;query='';document.getElementById('search').value='';document.querySelectorAll('[data-category]').forEach(b=>b.classList.toggle('selected',b===cat));document.querySelector('.gallery-heading h2').textContent=category==='All'?'The collection':category;renderGallery();return;}const tab=event.target.closest('[data-tab]');if(tab){currentTab=tab.dataset.tab;document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-selected',String(b===tab)));document.querySelector('.playground').hidden=currentTab==='source';document.getElementById('source-panel').hidden=currentTab!=='source';if(currentTab==='source')await showSource();return;}const anchor=event.target.closest('a[href]');if(!anchor||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey||anchor.target==='_blank'||anchor.hasAttribute('download'))return;const url=new URL(anchor.href);if(url.origin===location.origin){event.preventDefault();document.body.classList.remove('menu-open');navigate(url.pathname+url.search+url.hash);}});
document.addEventListener('keydown',event=>{if(event.key==='Escape')document.body.classList.remove('menu-open');if(event.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)){event.preventDefault();document.getElementById('search')?.focus();}});
async function copy(text,message){try{await navigator.clipboard.writeText(text);toast(message);}catch{toast('Select the text to copy it.');}}
let toastTimer;function toast(message){const el=document.querySelector('.toast');if(!el)return;el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2400);}
window.addEventListener('popstate',()=>{category='All';query='';limit=24;paused=false;clearTimeout(reloadTimer);render();});render();
